INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (364367, 15261, 'NPR', 'en', 'Meta heads to court in a landmark trial about kids and social media addiction', 'https://www.npr.org/2026/08/17/nx-s1-5930701/meta-trial-kids-social-media-addiction', 'Four states are suing the parent company of Facebook and Instagram, alleging that the platforms were designed to hook kids and that Meta hid the mental health risks.', 'https://npr.brightspotcdn.com/dims3/default/strip/false/crop/6240x3946+0+0/resize/6240x3946!/?url=http%3A%2F%2Fnpr-brightspot.s3.amazonaws.com%2F64%2F63%2F508040ce493baabbc494f357f4be%2Fgettyimages-1236190685.jpg', '2026-08-17T09:00:00+00:00', '2026-08-17T22:38:04.157292'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
