INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (365043, 15261, 'The Times of India', 'en', 'Meta goes to trial this week, which, if it loses, could change Insta & FB forever', 'https://timesofindia.indiatimes.com/world/us/meta-goes-to-trial-this-week-which-if-it-loses-could-change-insta-fb-forever/articleshow/133309246.cms', 'Meta has been hit with a major lawsuit regarding child safety and the addictive nature of its platform. Various states are demanding significant financial compensation and operational reforms, arguing that Meta intentionally crafted features to be addictive for young users. Additionally, they allege that the company collects data from children under the age of thirteen without obtaining proper consent.', 'https://static.toiimg.com/photo/msid-133309259,imgsize-62772.cms', '2026-08-18T01:45:57+00:00', '2026-08-18T03:05:27.166605'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
