INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (371195, 15261, 'The Guardian', 'en', 'US states take on Meta in pivotal trial over child social media addiction claims', 'https://www.theguardian.com/technology/2026/aug/18/meta-child-safety-addiction-lawsuit-states', 'State attorneys general allege that tech company intentionally designed addictive products that harm young people More than half of the states in the US have joined together in an unprecedented lawsuit against Meta that goes to trial on Tuesday, accusing the parent company of Instagram and Facebook of deliberately designing addictive products that lured in young people and caused them harm. The jury trial is taking place in federal court in Oakland, California , and is expected to last between six and eight weeks. The jury is expected to hear from Meta CEO Mark Zuckerberg , Instagram CEO Adam ', 'https://i.guim.co.uk/img/media/1b5ce85190e6d89e4db3acb2c4d28f253a101ac3/500_0_5000_4000/master/5000.jpg?width=140&quality=85&auto=format&fit=max&s=c420bb546a20a703516798696d6332b8', '2026-08-18T07:00:17+00:00', '2026-08-18T08:20:02.210760'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
