INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (365010, 15275, 'The Times of India', 'en', '74% big-turn deliveries: Manav Suthar out-turns Jadeja, Kuldeep in Galle', 'https://timesofindia.indiatimes.com/sports/cricket/india-vs-sri-lanka/manav-suthar-out-turns-ravindra-jadeja-kuldeep-yadav-with-74-big-turn-deliveries-in-galle/articleshow/133309017.cms', 'Manav Suthar played an important role in keeping the Sri Lankan batters under pressure. He also produced the highest percentage of deliveries with a large turn in the match so far. As many as 74% of his deliveries turned more than 4.5 degrees, the best among all the spinners. Suthar returned figures of 4/76 as India bowled Sri Lanka out for 284 after posting 462 in their first innings at the Galle International Stadium.', 'https://static.toiimg.com/photo/msid-133309032,imgsize-27258.cms', '2026-08-18T01:01:46+00:00', '2026-08-18T03:05:23.636378'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (366717, 15275, 'The Times of India', 'en', '''Sab talvaar chalayenge'': Pant''s hilarious Jadeja banter caught on stump mic', 'https://timesofindia.indiatimes.com/sports/cricket/india-vs-sri-lanka/sab-talvaar-chalayenge-rishabh-pants-hilarious-ravindra-jadeja-banter-with-sarfaraz-khan-caught-on-stump-mic-watch/articleshow/133310112.cms', 'India had reduced Sri Lanka to 99/5 by lunch, with Manav Suthar leading the attack. However, Ravindra Jadeja was yet to take a wicket at that stage. Sarfaraz Khan was heard telling Jadeja to remain patient, as the Indian bowlers would share the wickets among themselves.', 'https://static.toiimg.com/photo/msid-133310212,imgsize-49387.cms', '2026-08-18T03:06:02+00:00', '2026-08-18T03:58:57.059522'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
