INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (368667, 15275, 'Outlook India', 'en', 'IND Vs SL, 1st Test: ''Thank You, DDP’ KL Rahul’s Big Hug For Devdutt Padikkal After Crucial DRS Call', 'https://news.google.?oc=5', 'IND Vs SL, 1st Test: ''Thank You, DDP’ KL Rahul’s Big Hug For Devdutt Padikkal After Crucial DRS Call Outlook India', '', '2026-08-18T05:39:51+00:00', '2026-08-18T05:48:02.537266'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (369121, 15275, 'The Times of India', 'en', 'How Devdutt Padikkal''s alertness saved KL Rahul''s wicket in Galle', 'https://timesofindia.indiatimes.com/sports/cricket/india-vs-sri-lanka/how-devdutt-padikkals-alertness-saved-kl-rahuls-wicket-in-galle-watch/articleshow/133312838.cms', 'KL Rahul looked set to walk back when Prabath Jayasuriya trapped him on the back pad in the 11th over. KL Rahul was not confident about taking the review and was almost walking back. But Padikkal quickly asked him to review the decision. It turned out to be a crucial call. KL Rahul looked relieved and gave Padikkal a big hug, thanking his partner for convincing him to take the review.', 'https://static.toiimg.com/photo/msid-133312976,imgsize-47851.cms', '2026-08-18T05:50:52+00:00', '2026-08-18T06:39:27.406339'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
