INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (356325, 15307, 'The Times of India', 'en', 'Ferrari’s first all-electric car sells for $40M, nearly 40 times initial estimate of $1.1M', 'https://timesofindia.indiatimes.com/world/us/ferraris-first-all-electric-car-sells-for-40-million-at-charity-auction-nearly-40-times-initial-estimate-of-1-1-million-buyer-wont-receive-it-until-2027/articleshow/133279287.cms', 'Ferrari’s first all-electric car, the bespoke Luce “Chassis 0,” has sold for a record $40 million at a charity auction in Monterey, nearly 40 times its initial $1.1 million estimate. The sale makes it the most expensive new car ever auctioned, while the buyer will have to wait until 2027 for delivery.', 'https://static.toiimg.com/photo/msid-133279514,imgsize-33060.cms', '2026-08-16T17:17:57+00:00', '2026-08-17T05:36:37.257348'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
