INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (366811, 15307, 'Aaj Tak', 'hi', '382 करोड़ में बिकी FERRARI की पहली EV, किसने खरीदी ये कार', 'https://www.aajtak.in/auto/news/story/ferrari-luce-electric-car-auctioned-who-buys-first-production-unit-chassis-0-price-40-million-dollar-auaw-dskc-2624422-2026-08-18', 'Ferrari Luce: लॉन्च के वक्त फेरारी की इस इलेक्ट्रिक कार के डिजाइन की खूब आलोचना हुई थी. बावजूद इसके कंपनी का दावा है कि, इसके टार्गेटेड सभी 500 यूनिट की बिक्री हो चुकी है. इसके पहले यूनिट 382.4 करोड़ रुपये में नीलाम किया गया है. तो आइये जानें क्यों ख़ास है ये कार और किसने खरीदा है इसे.', '', '2026-08-18T03:07:21+00:00', '2026-08-18T03:59:35.977258'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
