INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (365018, 15309, 'The Times of India', 'en', 'US Supreme Court again rejects Trump''s bid to overturn $5mn E Jean Carroll verdict', 'https://timesofindia.indiatimes.com/world/us/us-supreme-court-again-rejects-donald-trumps-bid-to-overturn-5-million-e-jean-carroll-verdict/articleshow/133309489.cms', 'The US Supreme Court again rejected Donald Trump''s attempt to overturn a civil verdict. A jury had previously found him liable for sexual abuse and defamation against E. Jean Carroll. This decision leaves a $5 million judgment in place, which Trump has now paid. Another separate $83.3 million verdict against Trump is still pending before the Supreme Court.', 'https://static.toiimg.com/photo/msid-133309578,imgsize-968088.cms', '2026-08-18T02:16:39+00:00', '2026-08-18T03:05:23.732655'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
